// Race checkpoints & evidence-labelled performance estimates.
const RACES=[{name:'Ryde 10',date:'2027-02-07',distance:10,unit:'mi'},{name:'Solent Half',date:'2027-03-14',distance:13.1094,unit:'mi'},{name:'Madrid Marathon',date:'2027-04-25',distance:26.2188,unit:'mi'}];
function secondsRace(s){if(!s)return null;const a=String(s).split(':').map(Number);if(!a.length||a.some(x=>!Number.isFinite(x)||x<0))return null;return a.reduce((total,v)=>total*60+v,0);}
function raceFormat(sec){if(!Number.isFinite(sec)||sec<0)return '—';const total=Math.round(sec),hrs=Math.floor(total/3600),mins=Math.floor(total/60)%60,secs=total%60;return hrs?`${hrs}:${pad(mins)}:${pad(secs)}`:`${mins}:${pad(secs)}`;}
async function raceProjections(){const rec=await get('settings','raceRecords')||{},measures=[['5k',3.10686],['10k',6.21371],['10mile',10],['half',13.1094],['marathon',26.2188]];const bases=measures.map(([k,d])=>({key:k,distance:d,sec:secondsRace(rec[k])})).filter(x=>x.sec&&x.sec>0);let basis=bases.find(x=>x.key==='half')||bases.find(x=>x.key==='10mile')||bases.find(x=>x.key==='10k')||bases[0]||null;
 const actualRaces=(await all('activities')).filter(a=>a.type==='run'&&a.subtype==='Race'&&Number(a.distanceMiles)>1&&(Number(a.durationSeconds)>0||Number(a.durationMinutes)>0)).sort((a,b)=>b.date.localeCompare(a.date));
 const recentRace=actualRaces.find(a=>a.date>=addDays(TODAY(),-120));if(recentRace)basis={key:`race on ${recentRace.date}`,distance:Number(recentRace.distanceMiles),sec:Number(recentRace.durationSeconds)||Number(recentRace.durationMinutes)*60};
 return RACES.map(r=>({ ...r, days:daysBetween(TODAY(),r.date),estimate:basis?raceFormat(basis.sec*Math.pow(r.distance/basis.distance,1.06)):null,basis:basis?.key||null}));}
async function racesMarkup(){const rows=await raceProjections();return `<section class="card v11-races"><div class="goal-head"><div><strong>🏁 Race checkpoints</strong><small>Progression to Madrid — the training plan remains yours to choose</small></div><span class="pill">2027</span></div>${rows.map(r=>`<div class="v11-race"><div><strong>${esc(r.name)}</strong><small>${dateLabel(r.date)} · ${r.days>=0?r.days+' days away':'Completed / past'}</small></div><div><b>${r.estimate||'—'}</b><small>${r.estimate?'Illustrative pace projection':'Set PBs to estimate'}</small></div></div>`).join('')}<p class="metric-sub">Projections use an approximate distance-conversion formula based on your manually recorded PB. They are not guaranteed race results, and marathon endurance may differ substantially.</p><button class="secondary-btn" id="v11RaceWhy">How are these estimated?</button></section>`;}
async function goalInsightCard(){const p=state.profile,rows=await weightRows();const recent=rows.filter(w=>w.date>=addDays(TODAY(),-27));const nRows=(await all('nutrition')).filter(n=>n.date>=addDays(TODAY(),-27)&&n.calories!=null);
 const last=recent.slice(-7),early=recent.slice(0,7);const lastAvg=last.length>=5?avg(last.map(r=>Number(r.value))):null,earAvg=early.length>=5?avg(early.map(r=>Number(r.value))):null;
 const flat=recent.length>=21&&lastAvg!=null&&earAvg!=null&&Math.abs(lastAvg-earAvg)<.5;
 const used=flat?`Your recent weight trend is broadly flat (${lastAvg.toFixed(1)} vs ${earAvg.toFixed(1)} lb). ${nRows.length>=14?'Review adherence, activity, sleep and weekends before considering whether any calorie change is justified.':'Nutrition history is still limited, so there is not enough evidence for an adjustment.'}`:`The app waits for at least three weeks of weigh-ins before raising a possible plateau. One flat week is normal variation.`;
 const success=p.maintenanceMode?`Maintenance mode is active. Your objective is staying near ${p.maintenanceWeight||p.ultimateWeight} lb, not losing as fast as possible.`:`At ${p.ultimateWeight} lb, maintenance can replace weight-loss coaching with a stable target range.`;
 return `<section class="card v11-plateau"><div class="goal-head"><div><strong>${flat?'⚖️ Possible plateau':'⚖️ Weight-trend watch'}</strong><small>${recent.length} weigh-in days in the last 28</small></div><span class="pill ${flat?'watch':'good'}">${flat?'REVIEW':'MONITOR'}</span></div><p>${esc(used)}</p><div class="notice"><strong>${p.maintenanceMode?'Maintaining':'Long-term maintenance'}</strong><p>${esc(success)}</p></div><button class="secondary-btn" id="v11Maintenance">${p.maintenanceMode?'Review maintenance settings':'Set up maintenance for later'}</button></section>`;}
async function insightMarkup(){
 const [checks,habits,nuts,activities]=await Promise.all([all('checkins'),all('habits'),all('nutrition'),all('activities')]);const byHab=new Map(habits.map(h=>[h.date,h])),byNut=new Map(nuts.map(n=>[n.date,n]));const points=checks.filter(c=>c.id.startsWith('daily_')&&c.date>=state.profile.startDate);
 const items=[];function compare(key,tag,arr,selector,desc){if(arr.length<10){items.push({name:tag,detail:`Building signal: ${arr.length}/10 comparable days.`,confidence:'Not enough data'});return;}
 const g1=arr.filter(x=>selector(x)),g2=arr.filter(x=>!selector(x));if(g1.length<3||g2.length<3){items.push({name:tag,detail:'Need at least 3 days in each group to compare.',confidence:'Not enough data'});return;}
 const a=avg(g1.map(x=>x.value)),b=avg(g2.map(x=>x.value));items.push({name:tag,detail:desc(a,b,g1.length,g2.length),confidence:'Observational — no causation'});}
 compare('sleep','Sleep vs Momentum',points.filter(c=>c.sleepHours!=null&&byHab.has(c.date)).map(c=>({value:momentum(byHab.get(c.date)).earned,sleep:c.sleepHours})),x=>x.sleep>=7,(a,b,n1,n2)=>`After 7h+ sleep: ${Math.round(a)} average Momentum (${n1} days). Under 7h: ${Math.round(b)} (${n2} days).`);
 compare('protein','Protein vs hunger',points.filter(c=>c.hunger!=null&&byNut.get(c.date)?.protein!=null).map(c=>({value:Number(c.hunger),protein:Number(byNut.get(c.date).protein)})),x=>x.protein>=(state.profile.proteinTarget||130),(a,b,n1,n2)=>`When protein hit target: hunger ${a.toFixed(1)}/5 (${n1} days) versus ${b.toFixed(1)}/5 otherwise (${n2} days).`);
 compare('screens','Screen time vs bedtime',points.filter(c=>c.bedtimeActual&&c.screenTimeMinutes!=null).map(c=>({value:bedtimeDelta(c.bedtimeActual,state.profile.bedtimeTarget||'22:30'),screen:c.screenTimeMinutes})),x=>x.screen<=240,(a,b,n1,n2)=>`On ≤4h screen days: bedtime averaged ${Math.round(a)} min from target (${n1} days) vs ${Math.round(b)} min on longer-screen days (${n2} days).`);
 const weights=await weightRows(),wm=new Map(weights.map(w=>[w.date,Number(w.value)]));
 const mealRows=points.filter(c=>c.lastMealTime&&wm.has(c.date)&&wm.has(addDays(c.date,1))).map(c=>({late:c.lastMealTime>='21:00',value:wm.get(addDays(c.date,1))-wm.get(c.date)}));
 compare('meal','Last meal timing vs next weigh-in',mealRows,x=>!x.late,(a,b,n1,n2)=>`Earlier last meals: next-day scale change averaged ${a>=0?'+':''}${a.toFixed(2)} lb (${n1} nights), versus ${b>=0?'+':''}${b.toFixed(2)} lb after 21:00+ (${n2} nights). Water and food mass can influence these readings.`);
 const weekBed=points.filter(c=>c.bedtimeActual).map(c=>({weekday:parseLocal(c.date).getDay(),delta:bedtimeDelta(c.bedtimeActual,state.profile.bedtimeTarget||'22:30')}));
 if(weekBed.length>=10){const mondays=weekBed.filter(x=>x.weekday===1),other=weekBed.filter(x=>x.weekday!==1);if(mondays.length>=3&&other.length>=4)items.push({name:'Monday bedtime pattern',detail:`Mondays averaged ${Math.round(avg(mondays.map(x=>x.delta)))} minutes from target, versus ${Math.round(avg(other.map(x=>x.delta)))} minutes on other days. Explore schedule differences before attributing a cause.`,confidence:'Descriptive only'});}
 const duration=activities.filter(a=>a.startTime&&a.durationSeconds).length;
 items.push({name:'Activity timing',detail:`${duration} activities with start time and precise duration recorded. Comparisons with sleep and hunger will improve as this grows.`,confidence:'Collecting observations'});
 return `<section class="card"><div class="goal-head"><div><strong>🔎 Personal Insights</strong><small>Only surfaced once groups contain enough observations</small></div><span class="pill">OFFLINE</span></div>${items.map(x=>`<div class="v11-insight"><strong>${esc(x.name)}</strong><p>${esc(x.detail)}</p><small>${esc(x.confidence)}</small></div>`).join('')}<p class="metric-sub">These are associations in your self-logged data, not proof of cause. Missing or inaccurate entries can change the comparisons.</p></section>`;
}
