// Real monthly focus and maintenance choices (user-controlled, never silently adjusted).
async function openGoalReview(focus='stepTarget'){
 const p=state.profile,settings=await metaStore()||{},fields=[['stepTarget','Daily step target'],['proteinTarget','Protein target (g)'],['waterTarget','Water target (L)'],['fibreTarget','Fibre target (g)'],['calorieTarget','Rest-day calories']];
 modal(`<div class="modal-head"><div><h2>Goals and monthly focus</h2><p>Keep meaningful goals, adapt their difficulty deliberately.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="v11Goals" class="form-grid"><div class="field"><label>Focus for ${fmtDate(TODAY(),{month:'long'})}</label><select name="monthlyFocus">${opts([['nutrition','Nutrition consistency'],['strength','Strength routine'],['steps','Sensible daily movement'],['recovery','Recovery and sleep'],['learning','Daily learning'],['running','Running progress']],settings.monthlyFocus||'nutrition')}</select></div>${fields.map(([key,label])=>`<div class="field"><label>${label}${key===focus?' · suggested to review':''}</label><input name="${key}" type="number" min="0" step="${key==='waterTarget'||key==='fibreTarget'?'0.01':'1'}" value="${p[key]??''}"></div>`).join('')}<button class="primary-btn wide">Save goals</button></form>`);
 document.getElementById('v11Goals').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),updates={};for(const [key] of fields)if(f.get(key)!=='')updates[key]=Number(f.get(key));state.profile={...p,...updates,updatedAt:nowIso()};await put('profile',state.profile);await updateMeta({monthlyFocus:f.get('monthlyFocus')});closeModal();toast('Goals updated intentionally');render();};
}
async function maintenanceModal(){const p=state.profile;modal(`<div class="modal-head"><div><h2>Maintenance mode</h2><p>For when the goal becomes staying at a lower weight rather than losing further.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="v11MaintenanceForm" class="form-grid"><div class="field"><label>Mode</label><select name="mode">${opts([['loss','Continue weight loss'],['maintenance','Maintenance / defend the range']],p.maintenanceMode?'maintenance':'loss')}</select></div><div class="form-grid cols-2"><div class="field"><label>Centre weight (lb)</label><input type="number" step="0.1" name="weight" value="${p.maintenanceWeight||p.ultimateWeight||180}"></div><div class="field"><label>Allowed range ± lb</label><input type="number" min="1" step="0.5" name="range" value="${p.maintenanceRange||3}"></div></div><p class="metric-sub">Switching modes never secretly changes calories. Set and review your rest-day target separately based on sustained weight trends.</p><button class="primary-btn wide">Save maintenance settings</button></form>`);document.getElementById('v11MaintenanceForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),active=f.get('mode')==='maintenance';state.profile={...p,maintenanceMode:active,maintenanceWeight:Number(f.get('weight')),maintenanceRange:Number(f.get('range')),updatedAt:nowIso()};await put('profile',state.profile);closeModal();toast(active?'Maintenance tracking enabled':'Weight-loss tracking retained');render();};}

// Offline history and portable CSV export. JSON backup remains the disaster recovery method.
async function openHistoryModal(){const acts=await all('activities'),weights=await weightRows(),notes=await all('journal'),reports=await all('dailyReports'),checks=await all('checkins');const rows=[...acts.map(x=>({type:'Activity',date:x.date,text:`${x.title||x.type} ${x.distanceMiles||''} mi ${x.caloriesBurned??''} kcal`,id:x.id})),...weights.map(x=>({type:'Weight',date:x.date,text:`${x.value} lb`})),...notes.map(x=>({type:'Note',date:x.date||x.createdAt?.slice(0,10)||'',text:x.note||x.text||x.title||''})),...reports.map(x=>({type:'Report',date:x.date,text:`${x.score}/100 · ${x.tone||''}`})),...checks.filter(x=>x.id.startsWith('daily_')).map(x=>({type:'Check-in',date:x.date,text:`Energy ${x.energy??'—'} · Hunger ${x.hunger??'—'} · Sleep ${x.sleepHours??'—'}h`}))].filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x.date)).sort((a,b)=>b.date.localeCompare(a.date));
 const paint=(q='',kind='All')=>{const body=document.getElementById('v11HistoryRows');if(!body)return;const filtered=rows.filter(x=>(kind==='All'||x.type===kind)&&`${x.date} ${x.type} ${x.text}`.toLowerCase().includes(q.toLowerCase())).slice(0,100);body.innerHTML=filtered.length?filtered.map(x=>`<div class="v11-history-row"><strong>${dateLabel(x.date)} · ${x.type}</strong><small>${esc(x.text)}</small></div>`).join(''):'<p class="empty">No matching entries.</p>';};
 modal(`<div class="modal-head"><div><h2>Search your history</h2><p>Your local records. Results are not sent anywhere.</p></div><button class="close-btn" data-close-modal>×</button></div><div class="form-grid cols-2"><div class="field"><label>Search</label><input id="v11HistoryQuery" placeholder="tempo, 3 Nov, 212..."></div><div class="field"><label>Type</label><select id="v11HistoryType">${opts(['All','Weight','Activity','Check-in','Report','Note'].map(x=>[x,x]),'All')}</select></div></div><div id="v11HistoryRows"></div>`);const q=document.getElementById('v11HistoryQuery'),t=document.getElementById('v11HistoryType');q.oninput=t.onchange=()=>paint(q.value,t.value);paint();}
function toCSV(rows,headers){const escapeCell=x=>`"${String(x==null?'':typeof x==='object'?JSON.stringify(x):x).replaceAll('"','""')}"`;return [headers.join(','),...rows.map(row=>headers.map(h=>escapeCell(row[h])).join(','))].join('\r\n');}
function downloadCSV(name,raw){const blob=new Blob(['\ufeff',raw],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),15000);}
async function exportCSV(selected=null){const map={weight:[(await weightRows()).map(w=>({date:w.date,weight_lb:w.value,source:w.source})),['date','weight_lb','source']],nutrition:[await all('nutrition'),['date','calories','protein','fibre','fruitVeg','eatingFeel']],activities:[await all('activities'),['date','startTime','type','subtype','distanceMiles','durationSeconds','caloriesBurned','effort','feel','enjoyment','notes']],habits:[await all('habits'),['date','nutrition','protein','fibre','stepsValue','waterLitres','vitamins','learning','training']],checkins:[await all('checkins'),['date','energy','hunger','sleepHours','bedtimeActual','screenTimeMinutes','socialMediaMinutes','topApp','topAppMinutes','lastMealTime','eveningRating','eveningWins','eveningChallenges']],reports:[await all('dailyReports'),['date','score','tone','summary','nextFocus']]};if(selected && map[selected]){const [rows,headers]=map[selected];downloadCSV(`HealthDashboard-${selected}-${TODAY()}.csv`,toCSV(rows,headers));toast(`${selected} CSV prepared`);return;}
 modal(`<div class="modal-head"><div><h2>Export CSV</h2><p>Choose one dataset to download. Your encrypted .healthdash file remains the full restore backup.</p></div><button class="close-btn" data-close-modal>×</button></div><div class="v11-tools">${Object.keys(map).map(name=>`<button class="secondary-btn" data-csv="${name}">${name[0].toUpperCase()+name.slice(1)}</button>`).join('')}</div>`);
 document.querySelectorAll('[data-csv]').forEach(b=>b.onclick=()=>exportCSV(b.dataset.csv));}

