// Reminder times work offline while the PWA is open. True closed-app push is explicitly not claimed.
async function reminderSettings(){const s=await metaStore()||{};const r=s.reminders||{enabled:false,morning:'07:00',vitamins:'12:00',evening:'21:00',weekly:'19:30'};
 modal(`<div class="modal-head"><div><h2>Reminders</h2><p>In-app reminders work offline when Health Dashboard is open. Background alerts while closed need a separate notification implementation.</p></div><button class="close-btn" data-close-modal>×</button></div><form id="v11Reminders" class="form-grid"><label class="v11-inline"><input type="checkbox" name="enabled" ${r.enabled?'checked':''}> Enable gentle in-app reminders</label>${[['morning','Morning check-in'],['vitamins','Supplements'],['evening','Close Today'],['weekly','Sunday review']].map(([k,label])=>`<div class="field"><label>${label}</label><input type="time" name="${k}" value="${r[k]||''}"></div>`).join('')}<button class="primary-btn wide">Save reminders</button></form>`);
 document.getElementById('v11Reminders').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await updateMeta({reminders:{enabled:!!f.get('enabled'),morning:f.get('morning'),vitamins:f.get('vitamins'),evening:f.get('evening'),weekly:f.get('weekly')}});closeModal();render();};}
async function reminderCard(){const prefs=await metaStore()||{},r=prefs.reminders;if(!r?.enabled)return '';const now=timeNow(),h=await habitFor(),hasReport=await get('dailyReports',TODAY());let title=null,copy='';if(now>=r.morning&&!h.checkin&&now<'12:00'){title='☀️ Morning check-in is waiting';copy='A realistic morning plan gives the coach useful context.';}
 else if(now>=r.vitamins&&!h.vitamins&&!hasReport&&now<'19:00'){title='💊 Supplements still open';copy='A small checklist win is available whenever it suits you.';}
 else if(now>=r.evening&&!hasReport){title='🌙 Close Today is available';copy='Take a minute to record what went well and one focus for tomorrow.';}
 else if(parseLocal(TODAY()).getDay()===0&&now>=r.weekly){title='📊 Weekly review';copy='Bank the week and choose your next focus.';}
 return title?`<section class="v11-notice"><strong>${title}</strong><p>${esc(copy)}</p></section>`:'';
}

// Educational explanations for important calculated insights.
async function whyModal(kind){const meta={brief:['Coach’s Briefing','Uses previous reports, the latest check-in, the planned training and injury state. It selects a few meaningful observations; it does not establish that one event caused another.'],race:['Race estimates','When a manual PB is recorded, an approximate Riegel distance model (time × distance ratio^1.06) projects other distances. Terrain, training and endurance may make actual results very different.'],calories:['Adaptive calories','Today’s target starts from the manually chosen rest-day intake and adds a controlled part of the planned exercise estimate. Garmin numbers are estimates; the full burn is not automatically eaten back. Any adjustments need longer-term weight and adherence data.'],xp:['Momentum and XP','Daily Momentum scores behaviour; when a day is banked, earned points become lifetime XP. XP does not go backwards when a day is difficult.']};const [title,text]=(meta[kind]||meta.brief);modal(`<div class="modal-head"><div><h2>Why am I seeing this?</h2></div><button class="close-btn" data-close-modal>×</button></div><h3>${title}</h3><p>${esc(text)}</p>`);}

